/* B"H */
#include <windows.h>
#include <gl/gl.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>

#ifndef AWTS_MERKAVA_REPORT_JSON
#define AWTS_MERKAVA_REPORT_JSON "{\"BH\":\"B'H\",\"warning\":\"native report header missing\"}"
#endif

static int g_running = 1;
static int g_frames = 0;
static unsigned int g_bytecode_len = 0;
static unsigned int g_bytecode_ok = 0;
static unsigned int g_section = 0;
static unsigned int g_version = 0;

typedef struct AwtsTextFile { char* data; long size; } AwtsTextFile;

typedef struct AwtsWebGlCommandTable {
  unsigned int viewport;
  unsigned int clearColor;
  unsigned int clear;
  unsigned int drawArrays;
  unsigned int createBuffer;
  unsigned int bindBuffer;
  unsigned int bufferData;
  unsigned int createShader;
  unsigned int shaderSource;
  unsigned int compileShader;
  unsigned int createProgram;
  unsigned int linkProgram;
  unsigned int useProgram;
} AwtsWebGlCommandTable;

static int ends_with(const char* s, const char* suffix) {
  size_t a = strlen(s), b = strlen(suffix);
  return a >= b && _stricmp(s + a - b, suffix) == 0;
}

static AwtsTextFile read_text_file(const char* path) {
  AwtsTextFile out;
  out.data = NULL;
  out.size = 0;
  FILE* f = fopen(path, "rb");
  if (!f) return out;
  fseek(f, 0, SEEK_END);
  out.size = ftell(f);
  fseek(f, 0, SEEK_SET);
  out.data = (char*)calloc((size_t)out.size + 1, 1);
  if (out.data) fread(out.data, 1, (size_t)out.size, f);
  fclose(f);
  return out;
}

static unsigned int count_token(const char* text, const char* token) {
  unsigned int count = 0;
  const char* p = text;
  size_t n = strlen(token);
  while (p && *p) {
    p = strstr(p, token);
    if (!p) break;
    count++;
    p += n;
  }
  return count;
}

static int text_has(const char* text, const char* token) {
  return strstr(text, token) != NULL;
}

static int contains_any_node_core_except_fs(const char* text) {
  return strstr(text, "require(\"http\")") || strstr(text, "require('http')") ||
         strstr(text, "require(\"https\")") || strstr(text, "require('https')") ||
         strstr(text, "require(\"crypto\")") || strstr(text, "require('crypto')") ||
         strstr(text, "import http") || strstr(text, "from \"http\"") || strstr(text, "from 'http'");
}

static const char* quoted_path_after(const char* text, const char* marker, char* out, size_t cap) {
  const char* p = strstr(text, marker);
  if (!p) return NULL;
  p = strchr(p, '(');
  if (!p) return NULL;
  while (*p && *p != '\'' && *p != '"') p++;
  if (!*p) return NULL;
  char q = *p++;
  size_t n = 0;
  while (*p && *p != q && n + 1 < cap) out[n++] = *p++;
  out[n] = 0;
  return out;
}

static void print_fs_exists(const char* path) {
  DWORD attrs = GetFileAttributesA(path);
  printf("fs.existsSync(%s)=%s\n", path, attrs == INVALID_FILE_ATTRIBUTES ? "false" : "true");
}

static void print_fs_stat(const char* path) {
  WIN32_FILE_ATTRIBUTE_DATA data;
  if (!GetFileAttributesExA(path, GetFileExInfoStandard, &data)) {
    printf("fs.statSync(%s)=error:not_found\n", path);
    return;
  }
  ULARGE_INTEGER size;
  size.LowPart = data.nFileSizeLow;
  size.HighPart = data.nFileSizeHigh;
  printf("fs.statSync(%s).size=%llu isDirectory=%s\n", path, (unsigned long long)size.QuadPart, (data.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) ? "true" : "false");
}

static void print_fs_read(const char* path) {
  AwtsTextFile file = read_text_file(path);
  if (!file.data) { printf("fs.readFileSync(%s)=error:not_found\n", path); return; }
  unsigned int preview = file.size < 64 ? (unsigned int)file.size : 64;
  printf("fs.readFileSync(%s).bytes=%ld preview=", path, file.size);
  for (unsigned int i = 0; i < preview; i++) {
    char c = file.data[i];
    putchar((c == '\n' || c == '\r') ? ' ' : c);
  }
  putchar('\n');
  free(file.data);
}

static void print_fs_readdir(const char* dir) {
  char pattern[MAX_PATH];
  snprintf(pattern, sizeof(pattern), "%s\\*", dir);
  WIN32_FIND_DATAA fd;
  HANDLE h = FindFirstFileA(pattern, &fd);
  unsigned int count = 0;
  if (h == INVALID_HANDLE_VALUE) { printf("fs.readdirSync(%s)=error:not_found\n", dir); return; }
  printf("fs.readdirSync(%s)=", dir);
  do {
    if (strcmp(fd.cFileName, ".") && strcmp(fd.cFileName, "..")) {
      if (count) printf(",");
      printf("%s", fd.cFileName);
      count++;
    }
  } while (FindNextFileA(h, &fd) && count < 20);
  FindClose(h);
  printf(" count=%u\n", count);
}

static int execute_simple_fs_js(const char* scriptPath, const char* text) {
  int hasFs = strstr(text, "require('fs')") || strstr(text, "require(\"fs\")");
  if (!hasFs) return 0;
  char target[MAX_PATH];
  printf("native-fs-runtime=active entry=%s\n", scriptPath);
  if (quoted_path_after(text, "existsSync", target, sizeof(target))) print_fs_exists(target);
  if (quoted_path_after(text, "readFileSync", target, sizeof(target))) print_fs_read(target);
  if (quoted_path_after(text, "statSync", target, sizeof(target))) print_fs_stat(target);
  if (quoted_path_after(text, "readdirSync", target, sizeof(target))) print_fs_readdir(target);
  printf("native-fs-runtime=status:partial-pattern-executor\n");
  return 1;
}

static AwtsWebGlCommandTable scan_webgl(const char* text) {
  AwtsWebGlCommandTable t;
  memset(&t, 0, sizeof(t));
  t.viewport = count_token(text, "viewport(");
  t.clearColor = count_token(text, "clearColor(");
  t.clear = count_token(text, "clear(");
  t.drawArrays = count_token(text, "drawArrays(");
  t.createBuffer = count_token(text, "createBuffer(");
  t.bindBuffer = count_token(text, "bindBuffer(");
  t.bufferData = count_token(text, "bufferData(");
  t.createShader = count_token(text, "createShader(");
  t.shaderSource = count_token(text, "shaderSource(");
  t.compileShader = count_token(text, "compileShader(");
  t.createProgram = count_token(text, "createProgram(");
  t.linkProgram = count_token(text, "linkProgram(");
  t.useProgram = count_token(text, "useProgram(");
  return t;
}

static void print_webgl_table(const char* text) {
  AwtsWebGlCommandTable t = scan_webgl(text);
  printf("webgl-command-table: viewport=%u clearColor=%u clear=%u drawArrays=%u createBuffer=%u bindBuffer=%u bufferData=%u createShader=%u shaderSource=%u compileShader=%u createProgram=%u linkProgram=%u useProgram=%u\n",
    t.viewport, t.clearColor, t.clear, t.drawArrays, t.createBuffer, t.bindBuffer, t.bufferData,
    t.createShader, t.shaderSource, t.compileShader, t.createProgram, t.linkProgram, t.useProgram);
}

static void print_help(void) {
  printf("B'H Merkava Native Browser / Runtime Executor\n");
  printf("Usage:\n");
  printf("  merkavaapp.exe                     launch sample.merkava in native OpenGL browser\n");
  printf("  merkavaapp.exe sample.merkava      load Merkava bytecode\n");
  printf("  merkavaapp.exe --check file.js     parse/analyze JS/HTML/bytecode without launching browser\n");
  printf("  merkavaapp.exe file.js             run supported native JS patterns; report unsupported APIs\n");
  printf("  merkavaapp.exe file.html           analyze HTML entry, linked scripts, WebGL hints\n");
  printf("Native FS now: existsSync/readFileSync/statSync/readdirSync pattern executor.\n");
  printf("Native WebGL now: command table + OpenGL viewport/clear/drawArrays smoke.\n");
  printf("Not complete: full JS VM, module loader, http/https/crypto, full WebGL shaders/buffers/textures.\n");
}

static int load_merkava_file(const char* path) {
  FILE* f = fopen(path, "rb");
  if (!f) return 0;
  unsigned char head[8] = {0,0,0,0,0,0,0,0};
  fseek(f, 0, SEEK_END);
  long size = ftell(f);
  fseek(f, 0, SEEK_SET);
  fread(head, 1, 8, f);
  fclose(f);
  g_bytecode_len = size > 0 ? (unsigned int)size : 0;
  g_bytecode_ok = (size >= 5 && head[0] == 'M' && head[1] == 'D' && head[2] == '2' && head[3] == 0);
  g_section = head[4];
  g_version = head[5];
  return g_bytecode_ok ? 1 : 0;
}

static int analyze_js(const char* path, int checkOnly) {
  AwtsTextFile file = read_text_file(path);
  if (!file.data) { printf("B'H Merkava JS analyzer\nfile=%s error=not_found\n", path); return 2; }
  printf("B'H Merkava JS analyzer\n");
  printf("file=%s bytes=%ld lines=%u checkOnly=%d\n", path, file.size, count_token(file.data, "\n") + 1, checkOnly);
  printf("syntax-surface: functions=%u classes=%u imports=%u requires=%u awaits=%u fetch=%u\n",
    count_token(file.data, "function"), count_token(file.data, "class "), count_token(file.data, "import "),
    count_token(file.data, "require("), count_token(file.data, "await "), count_token(file.data, "fetch("));
  printf("browser-surface: document=%u window=%u webgl=%u canvas=%u\n",
    count_token(file.data, "document"), count_token(file.data, "window"), count_token(file.data, "webgl"), count_token(file.data, "canvas"));
  printf("fs-surface: existsSync=%u readFileSync=%u statSync=%u readdirSync=%u\n",
    count_token(file.data, "existsSync("), count_token(file.data, "readFileSync("), count_token(file.data, "statSync("), count_token(file.data, "readdirSync("));
  print_webgl_table(file.data);
  if (!checkOnly && execute_simple_fs_js(path, file.data)) { free(file.data); return 0; }
  if (contains_any_node_core_except_fs(file.data)) {
    printf("node-core-detected=true\n");
    printf("native-node-status=http/https/crypto/module-loader full execution not implemented in C yet; refusing to fake success\n");
    free(file.data);
    return checkOnly ? 0 : 7;
  }
  printf("node-core-detected=%s\n", text_has(file.data, "require('fs')") || text_has(file.data, "require(\"fs\")") ? "fs-only" : "false");
  printf("merkava-bytecode-path=available-via-build-pipeline native-c-vm=partial\n");
  free(file.data);
  return 0;
}

static int analyze_html(const char* path, int checkOnly) {
  AwtsTextFile file = read_text_file(path);
  if (!file.data) { printf("B'H Merkava HTML analyzer\nfile=%s error=not_found\n", path); return 2; }
  printf("B'H Merkava HTML analyzer\n");
  printf("file=%s bytes=%ld lines=%u checkOnly=%d\n", path, file.size, count_token(file.data, "\n") + 1, checkOnly);
  printf("html-surface: scriptTags=%u linkTags=%u canvasTags=%u styleTags=%u\n",
    count_token(file.data, "<script"), count_token(file.data, "<link"), count_token(file.data, "<canvas"), count_token(file.data, "<style"));
  print_webgl_table(file.data);
  printf("dom-status=native-tree-planned webgl-status=command-table-plus-opengl-smoke\n");
  free(file.data);
  return 0;
}

static LRESULT CALLBACK AwtsWndProc(HWND hwnd, UINT msg, WPARAM wp, LPARAM lp) {
  switch (msg) { case WM_CLOSE: case WM_DESTROY: g_running = 0; PostQuitMessage(0); return 0; }
  return DefWindowProc(hwnd, msg, wp, lp);
}

static void print_runtime_report(void) {
  printf("---- embedded Merkava runtime report ----\n");
  printf("%s\n", AWTS_MERKAVA_REPORT_JSON);
  printf("---- native capabilities ----\n");
  printf("dom=partial-native-tree webgl=command-table-plus-win32-opengl console=stdout bytecode-loader=fs\n");
  printf("node-native=fs-partial-pattern-executor http/https/crypto/module-loader not complete\n");
  printf("js-understanding=MerkavaASTParser+MerkavaBytecodeApi build-time report embedded; C VM partial\n");
}

static void draw_scene(void) {
  float pulse = (float)((g_frames % 120) / 120.0f);
  glViewport(0, 0, 960, 540);
  glClearColor(0.015f, 0.02f + pulse * 0.05f, 0.04f, 1.0f);
  glClear(GL_COLOR_BUFFER_BIT);
  glBegin(GL_TRIANGLES);
    glColor3f(1.0f, 0.25f, 0.15f); glVertex2f(-0.72f, -0.55f);
    glColor3f(0.1f, 0.9f, 0.35f);  glVertex2f( 0.72f, -0.55f);
    glColor3f(0.25f, 0.45f, 1.0f); glVertex2f( 0.00f,  0.72f);
  glEnd();
  glBegin(GL_LINE_LOOP);
    glColor3f(0.95f, 0.95f, 1.0f); glVertex2f(-0.86f, -0.78f);
    glColor3f(0.95f, 0.95f, 1.0f); glVertex2f( 0.86f, -0.78f);
    glColor3f(0.95f, 0.95f, 1.0f); glVertex2f( 0.86f,  0.78f);
    glColor3f(0.95f, 0.95f, 1.0f); glVertex2f(-0.86f,  0.78f);
  glEnd();
}

static int launch_browser(const char* bytecodePath) {
  int loaded = load_merkava_file(bytecodePath);
  printf("B'H Merkava Native Browser / Runtime Executor\n");
  printf("bytecode=%s bytes=%u ok=%u section=%u version=%u\n", bytecodePath, g_bytecode_len, g_bytecode_ok, g_section, g_version);
  print_runtime_report();
  fflush(stdout);
  HINSTANCE hInst = GetModuleHandle(NULL);
  WNDCLASS wc; ZeroMemory(&wc, sizeof(wc));
  wc.style = CS_OWNDC; wc.lpfnWndProc = AwtsWndProc; wc.hInstance = hInst; wc.lpszClassName = "AwtsMerkavaNativeBrowser"; wc.hCursor = LoadCursor(NULL, IDC_ARROW);
  if (!RegisterClass(&wc)) { printf("register_window_failed=%lu\n", GetLastError()); return 10; }
  HWND hwnd = CreateWindowEx(0, wc.lpszClassName, "B'H Merkava Native Browser - OpenGL/WebGL Bridge", WS_OVERLAPPEDWINDOW | WS_VISIBLE, CW_USEDEFAULT, CW_USEDEFAULT, 960, 540, NULL, NULL, hInst, NULL);
  if (!hwnd) { printf("create_window_failed=%lu\n", GetLastError()); return 11; }
  HDC dc = GetDC(hwnd);
  PIXELFORMATDESCRIPTOR pfd; ZeroMemory(&pfd, sizeof(pfd));
  pfd.nSize = sizeof(pfd); pfd.nVersion = 1; pfd.dwFlags = PFD_DRAW_TO_WINDOW | PFD_SUPPORT_OPENGL | PFD_DOUBLEBUFFER; pfd.iPixelType = PFD_TYPE_RGBA; pfd.cColorBits = 32; pfd.cDepthBits = 24; pfd.iLayerType = PFD_MAIN_PLANE;
  int pf = ChoosePixelFormat(dc, &pfd);
  if (!pf || !SetPixelFormat(dc, pf, &pfd)) { printf("pixel_format_failed=%lu\n", GetLastError()); return 12; }
  HGLRC rc = wglCreateContext(dc);
  if (!rc || !wglMakeCurrent(dc, rc)) { printf("opengl_context_failed=%lu\n", GetLastError()); return 13; }
  printf("opengl_vendor=%s\n", glGetString(GL_VENDOR));
  printf("opengl_renderer=%s\n", glGetString(GL_RENDERER));
  printf("opengl_version=%s\n", glGetString(GL_VERSION));
  fflush(stdout);
  MSG msg; DWORD start = GetTickCount();
  while (g_running && GetTickCount() - start < 2200) {
    while (PeekMessage(&msg, NULL, 0, 0, PM_REMOVE)) { if (msg.message == WM_QUIT) g_running = 0; TranslateMessage(&msg); DispatchMessage(&msg); }
    draw_scene(); SwapBuffers(dc); g_frames++; Sleep(16);
  }
  wglMakeCurrent(NULL, NULL); if (rc) wglDeleteContext(rc); ReleaseDC(hwnd, dc); DestroyWindow(hwnd);
  printf("frames=%d loaded=%d renderer=win32-opengl status=complete\n", g_frames, loaded);
  fflush(stdout);
  return loaded ? 0 : 2;
}

int main(int argc, char** argv) {
  if (argc > 1 && (!strcmp(argv[1], "--help") || !strcmp(argv[1], "-h"))) { print_help(); return 0; }
  if (argc > 1 && (!strcmp(argv[1], "--version") || !strcmp(argv[1], "-v"))) { printf("merkavaapp native 0.3.0\n"); return 0; }
  if (argc > 2 && !strcmp(argv[1], "--check")) {
    if (ends_with(argv[2], ".js")) return analyze_js(argv[2], 1);
    if (ends_with(argv[2], ".html") || ends_with(argv[2], ".htm")) return analyze_html(argv[2], 1);
    if (ends_with(argv[2], ".merkava")) { int ok = load_merkava_file(argv[2]); printf("B'H Merkava bytecode check\nfile=%s bytes=%u ok=%u section=%u version=%u\n", argv[2], g_bytecode_len, g_bytecode_ok, g_section, g_version); return ok ? 0 : 2; }
    printf("--check unsupported file type: %s\n", argv[2]); return 64;
  }
  if (argc > 1 && ends_with(argv[1], ".js")) return analyze_js(argv[1], 0);
  if (argc > 1 && (ends_with(argv[1], ".html") || ends_with(argv[1], ".htm"))) return analyze_html(argv[1], 0);
  const char* bytecodePath = argc > 1 ? argv[1] : "sample.merkava";
  return launch_browser(bytecodePath);
}
